import { computed, ref, watch } from 'vue'
import type { LocationQueryRaw } from 'vue-router'

export interface ChatTabLocation {
  path: string
  query: LocationQueryRaw
}

export interface UseChatTabTargetOptions {
  isChatRoute: () => boolean
  fullPath: () => string
  path: () => string
  query: () => LocationQueryRaw
}

// The mobile Chat tab is a "return" affordance: it must reopen the chat surface
// the operator actually left, not a freshly reset one. A bare /chat link
// defeats that — the chat mount logic deliberately opens a clean draft when no
// session is in the URL. Record the most recent chat location while a chat
// route is active and hand the tab that target. Leaving chat never clears the
// record, so Sessions/Overview detours keep the return intact.
//
// Draft nuance: /chat/new?agent=… is treated as an explicit fresh-task handoff
// on remount, which would discard an unsent draft. The tab therefore returns to
// the bare draft path (recent-draft recovery still applies) unless a project
// binding must survive the return.
export function useChatTabTarget(options: UseChatTabTargetOptions) {
  const lastChatLocation = ref<ChatTabLocation | null>(null)
  watch(
    options.fullPath,
    () => {
      if (!options.isChatRoute()) return
      const path = options.path()
      const query = options.query()
      if (path === '/chat/new' && !query.project) {
        lastChatLocation.value = { path, query: {} }
        return
      }
      lastChatLocation.value = { path, query: { ...query } }
    },
    { immediate: true },
  )
  const chatTabTarget = computed<string | ChatTabLocation>(
    () => lastChatLocation.value ?? '/chat',
  )
  return { lastChatLocation, chatTabTarget }
}
